import{_ as n,c as e,o as s,b0 as t}from"./chunks/framework.BpbtKNwe.js";const r="/aillm-docs/assets/3bc857c28224630d036b63997ce01a42.DxSN8Nj7.jpeg",l="/aillm-docs/assets/3a232db8dc71c90b2d6ce9d23fe05dff.Df54Tmk5.svg",p="/aillm-docs/assets/3717ecb8116906cfd9fe9694d290bba8.D9ordFij.svg",u=JSON.parse('{"title":"LV030-提示词工程","description":null,"frontmatter":{"title":"LV030-提示词工程","date":"2025-11-28T19:54:33.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/llm/basic/126b154d69690181f14561a8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-28T19:54:33.024Z","fulluuid":"1f14561a88274811b97725d240728350","useduuid":"1f14561a8"}},"headers":[],"relativePath":"sdoc/llm/basic/126b154d69690181f14561a8.md","filePath":"sdoc/05-LLM/05-LLM基础/LV030-提示词工程.md","lastUpdated":1767430713000}'),i={name:"sdoc/llm/basic/126b154d69690181f14561a8.md"};function o(d,a,c,h,b,m){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="lv030-提示词工程" tabindex="-1">LV030-提示词工程 <a class="header-anchor" href="#lv030-提示词工程" aria-label="Permalink to &quot;LV030-提示词工程&quot;">​</a></h1><p>我们来看看什么叫提示词工程（Prompt Engineering）</p><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><h3 id="_1-为什么我们的-ai-输出不尽人意" tabindex="-1">1. 为什么我们的 AI 输出不尽人意？ <a class="header-anchor" href="#_1-为什么我们的-ai-输出不尽人意" aria-label="Permalink to &quot;1. 为什么我们的 AI 输出不尽人意？&quot;">​</a></h3><ul><li>让 AI 写一篇文章，结果内容泛泛而谈，毫无重点？甚至编造一些不存在的内容？</li><li>提问技术问题，得到的回答却充满错误或过于简单？</li></ul><h3 id="_2-尝试一下" tabindex="-1">2. 尝试一下 <a class="header-anchor" href="#_2-尝试一下" aria-label="Permalink to &quot;2. 尝试一下&quot;">​</a></h3><p>我们来到 Deepseek 官网：<a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek - 探索未至之境</a>，打开一个对话框，输入以下内容：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">写一个hello world程序</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后就会看到大模型开始思考，然后开始给我们结果，然后就得到了一堆的内容，可能有好几百字。那我们只是想简单了解一下呢？我们换种问法：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">用户：写一篇关于AI的介绍,不要超过100字</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Deepseek：人工智能是让机器模拟人类智能的科学。其核心是机器学习，能从数据中学习规律，实现图像识别、语音交互、智能推荐等功能。AI正重塑各行各业，在提升效率的同时，也带来了就业、伦理等挑战，未来将更强调人机协作与负责任的发展。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这个时候，我们就会得到一个简短的回答，不会像上面一样好几百字蹦出来。</p><h2 id="二、提示词-prompt" tabindex="-1">二、提示词(Prompt) <a class="header-anchor" href="#二、提示词-prompt" aria-label="Permalink to &quot;二、提示词(Prompt)&quot;">​</a></h2><h3 id="_1-什么是提示词" tabindex="-1">1. 什么是提示词？ <a class="header-anchor" href="#_1-什么是提示词" aria-label="Permalink to &quot;1. 什么是提示词？&quot;">​</a></h3><p>提示词是传递给大语言模型（LLM, Large Language Model）的输入规范，用于约束模型行为、限定任务范围、控制输出格式。一个 Prompt 本质上是 <strong>任务描述 + 行为规约 + 输出约束</strong> 的组合。</p><p>优秀的提示词通常具备以下特征：</p><ul><li>指令明确（Directive）</li><li>上下文充足（Context）</li><li>示例有效（Exemplars）</li><li>格式固定（Format）</li><li>风格一致（Style）</li><li>无歧义（Disambiguation）</li></ul><h3 id="_2-工作原理" tabindex="-1">2. 工作原理 <a class="header-anchor" href="#_2-工作原理" aria-label="Permalink to &quot;2. 工作原理&quot;">​</a></h3><p>提示词在大语言模型中的作用可以分为以下几个阶段：</p><p>（1）<strong>Token 化与编码</strong>：Prompt 转换为 Token 序列，作为模型输入。</p><p>（2）<strong>上下文建模</strong>：模型根据已有知识理解意图，建立语境。</p><p>（3）<strong>概率预测</strong>：逐 token 预测最可能输出，生成响应内容。</p><p>（4）<strong>策略约束</strong>：通过 Temperature、Top-p 等采样策略控制生成过程。</p><p>（5）<strong>输出整形（Answer Engineering, Answer Engineering）</strong>：结构化、解析、验证输出结果。</p><p>提示词质量直接影响模型在上下文建模与概率预测阶段的推理行为，因此 Prompt 的结构与顺序设计会显著改变输出质量。</p><h3 id="_3-核心组成-结构视图" tabindex="-1">3. 核心组成（结构视图） <a class="header-anchor" href="#_3-核心组成-结构视图" aria-label="Permalink to &quot;3. 核心组成（结构视图）&quot;">​</a></h3><p>提示词可以拆解为 6 个结构单元。下表展示了提示词的核心组成及其功能。</p><table tabindex="0"><thead><tr><th style="text-align:left;">组成部分</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;">Role</td><td style="text-align:left;">设定模型的专业角色（审计员、工程师等）</td></tr><tr><td style="text-align:left;">Directive</td><td style="text-align:left;">告诉模型“要做什么”</td></tr><tr><td style="text-align:left;">Additional Info</td><td style="text-align:left;">背景知识、限制条件</td></tr><tr><td style="text-align:left;">Exemplars</td><td style="text-align:left;">Few-shot 示例</td></tr><tr><td style="text-align:left;">Format</td><td style="text-align:left;">输出格式规范（JSON/Markdown/表格）</td></tr><tr><td style="text-align:left;">Style</td><td style="text-align:left;">语气、风格（正式、简洁）</td></tr></tbody></table><p>这些元素共同形成“Prompt Schema”，是所有工程化 Prompt 的基础。</p><h2 id="二、提示词工程" tabindex="-1">二、提示词工程 <a class="header-anchor" href="#二、提示词工程" aria-label="Permalink to &quot;二、提示词工程&quot;">​</a></h2><h3 id="_1-什么是提示词工程" tabindex="-1">1. 什么是提示词工程 <a class="header-anchor" href="#_1-什么是提示词工程" aria-label="Permalink to &quot;1. 什么是提示词工程&quot;">​</a></h3><p>那么 Prompt Engineering（提示词工程）是什么？顾名思义，是围绕 &quot;提示词&quot;（Prompt）进行设计、构建和优化的过程，提示词工程通过设计优化输入提示词，引导大模型生成更精准的答案，类似于给大模型装上“人类语言翻译器”。</p><img src="`+r+'" alt="img" style="zoom:50%;"><p>简单来说，提示词工程是指如何设计、优化、调整输入给 AI 模型的提示词（Prompt），从而获得最有效、最准确的输出。</p><h3 id="_2-提示词的要素" tabindex="-1">2. 提示词的要素 <a class="header-anchor" href="#_2-提示词的要素" aria-label="Permalink to &quot;2. 提示词的要素&quot;">​</a></h3><p>如果我们接触过大量提示工程相关的示例和应用，会注意到提示词是由一些要素组成的。提示词可以包含以下任意要素：</p><p><strong>指令</strong>：想要模型执行的特定任务或指令。</p><p><strong>上下文</strong>：包含外部信息或额外的上下文信息，引导语言模型更好地响应。</p><p><strong>输入数据</strong>：用户输入的内容或问题。</p><p><strong>输出指示</strong>：指定输出的类型或格式，例如 json、markdown。</p><h3 id="_3-提示词工程-从技巧到体系化技术栈" tabindex="-1">3. 提示词工程：从技巧到体系化技术栈 <a class="header-anchor" href="#_3-提示词工程-从技巧到体系化技术栈" aria-label="Permalink to &quot;3. 提示词工程：从技巧到体系化技术栈&quot;">​</a></h3><p>提示词工程不仅仅依赖“经验”，而是一个系统化的技术体系。下图总结了 Prompt Engineering 的六大技术域及其代表方法：</p><p><img src="'+l+'" alt="图 2: Prompt Engineering 技术域与方法"></p><h3 id="_4-提示词工程的扩展领域" tabindex="-1">4. 提示词工程的扩展领域 <a class="header-anchor" href="#_4-提示词工程的扩展领域" aria-label="Permalink to &quot;4. 提示词工程的扩展领域&quot;">​</a></h3><p>随着模型能力增强，Prompt Engineering 已从“文本提示”扩展至多语、多模态、智能体、评估、安全等方向。下图展示了提示词工程的主要扩展领域：</p><p><img src="'+p+`" alt="图 3: Prompt Engineering 扩展域"></p><h2 id="三、-提示技术" tabindex="-1">三、 提示技术 <a class="header-anchor" href="#三、-提示技术" aria-label="Permalink to &quot;三、 提示技术&quot;">​</a></h2><h3 id="_1-zero-shot" tabindex="-1">1. Zero-shot <a class="header-anchor" href="#_1-zero-shot" aria-label="Permalink to &quot;1. Zero-shot&quot;">​</a></h3><p><strong>Zero-shot 提示</strong> 指的是模型在没有见过任何与特定任务相关的示例数据的情况下，直接执行该任务。简单来说，就是 <strong>零样本提示</strong>。在 Zero-shot 学习中，模型依赖其在预训练阶段获得的知识，能够根据输入的指令或描述，完成没有直接训练过的任务。</p><h3 id="_2-few-shot" tabindex="-1">2. Few-Shot <a class="header-anchor" href="#_2-few-shot" aria-label="Permalink to &quot;2. Few-Shot&quot;">​</a></h3><p><strong>Few-shot 提示</strong> 指的是模型通过少量的训练示例来完成任务。通常，few-shot 提示会提供一些示例（通常在 3 到 10 个之间），使得模型能够更好地理解任务的规律和要求，就是 <strong>少样本提示</strong>。就好像是在一场密室逃脱游戏中，AI 大语言模型拿到了一些关于任务的提示卡片，让它知道应该朝着什么方向前进。</p><h3 id="_3-思维链提示" tabindex="-1">3. 思维链提示 <a class="header-anchor" href="#_3-思维链提示" aria-label="Permalink to &quot;3. 思维链提示&quot;">​</a></h3><p>思维链的解释很简单，意思就是给 AI 大语言模型（ChatGPT）给出一些需要思考的过程，可以是我们直接给它提供，也可以让它自己来思考。</p><p><strong>少样本思维链</strong>：就好像在给 AI 大语言模型给出一些提示或者解题步骤，比如下面例子，第一次直接让 AI 大模型回到问题时，它直接给答案，但是是错误的。第二次通过在提示词中给出模型解题步骤，给出的答案就是正确的。</p><p><strong>【大模型的直接思考回答】</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问：小明现在有5个羽毛球。他买了2管羽毛球。</span></span>
<span class="line"><span>   每管有3个羽毛球。现在他有多少个羽毛球？</span></span>
<span class="line"><span>答：答案是11。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问：自助餐厅有23个苹果。如果他们用了20个来做午餐，</span></span>
<span class="line"><span>   并买了6个，他们现在有多少个苹果？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>模型输出</span></span>
<span class="line"><span>答：答案是27  【错误的❎】</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>【提示词中告诉模型解答步骤】</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问：小明现在有5个羽毛球。他买了2管羽毛球。</span></span>
<span class="line"><span>   每管有3个羽毛球。现在他有多少个羽毛球？</span></span>
<span class="line"><span>答：小明起初有5个羽毛球。2管每管3个羽毛球，总共6个羽毛球。</span></span>
<span class="line"><span>   5+6=11。答案是11。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问：自助餐厅有23个苹果。如果他们用了20个来做午餐，</span></span>
<span class="line"><span>   并买了6个，他们现在有多少个苹果？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>模型输出</span></span>
<span class="line"><span>答：自助餐厅最初有23个苹果。他们用了20个来做午餐。</span></span>
<span class="line"><span>   所以他们还剩下23-20=3个。他们买了6个苹果，</span></span>
<span class="line"><span>   所以现在他们有3+6=9个。答案是9   [正确的✅]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/EnjoyEDU/article/details/148734347" target="_blank" rel="noreferrer">大模型应用之提示词工程详解，提示词工程保姆级教程，收藏这篇就够了！_大模型 提示词工程-CSDN 博客</a></p><p><a href="https://arxiv.org/pdf/2402.07927" target="_blank" rel="noreferrer">ASystematic Survey of Prompt Engineering in Large Language Models: Techniques and Applications</a></p><p><a href="https://jimmysong.io/book/ai-handbook/prompt/overview/" target="_blank" rel="noreferrer">提示词工程概述 | Jimmy Song</a></p><p><a href="https://arxiv.org/pdf/2406.06608" target="_blank" rel="noreferrer">The Prompt Report: A Systematic Survey of Prompt Engineering Techniques</a></p><p><a href="https://docs.langchain.com/langsmith/prompt-engineering-concepts" target="_blank" rel="noreferrer">Prompt engineering concepts - Docs by LangChain</a></p></blockquote>`,58)])])}const f=n(i,[["render",o]]);export{u as __pageData,f as default};
